</template>

<script>
import processBar from "../../components/public/processBar.vue"
import dashboardView from "./dashboardView.vue"

// 红色
const red = '#d9001b'
// 蓝色
const blue = '#02a7f0'
// 默认灰色
const dc = '#bfc4cb'

export default {
    components: {
        processBar,
        dashboardView
    },
    props: {
        spinalData: Object,
        utype: {
            type: Number,
            default: 0 // 0青年 1男  2女
        }
    },
    data() {
        return {
            isDeviceReport: window.sessionStorage.getItem('isDeviceReport'),
            tabinx: 0,
            // 等级色值
            colorLevels: ["#51ED97", "#EAB04D", "#EB773B", "#FD3741"],
            // 等级
            0: 0,
            preScore: 0, // 当前状态评分
            preStatus: 0, // 当前状态值
            structureAssessmentDes: "脊柱整体排列基本正常", // 脊柱结论
            structuralDes: "",
            structuralArray: [
                [
                    "头部姿态和颈椎排列基本正常",
                    "存在明显的头部前倾或侧歪，颈椎排列轻度偏移",
                    "头部明显前倾或侧歪，颈椎排列中度偏移",
                    "头部严重前倾或侧歪，颈椎排列严重偏移"
                ],
                [
                    "胸椎排列基本正常，无明显结构异常",
                    "胸椎排列轻度偏移，可能对生活质量有轻微影响",
                    "胸椎排列中度偏移，可能影响姿势和生活质量",
                    "胸椎排列严重偏移，生物力线显著异常，可能造成疼痛及其他继发性问题"
                ],
                [
                    "腰椎排列正常，姿势平衡，无明显结构异常",
                    "腰椎排列轻度偏移，生物力线尚可，但长期可能引发姿势代偿",
                    "腰椎排列中度偏移，生物力线偏倚，可能影响姿势和生活质量",
                    "腰椎排列严重偏移，生物力线显著异常"
                ]
            ],
            errorTips: [
                [`肩胛提肌、胸锁乳突肌和斜方肌上束<span style="color:red;">紧张</span>，颈深屈肌<span style="color:#5E92DD;">无力</span>。建议加强颈部肌肉，并进行伸展运动。`,
                  `左侧胸锁乳突肌和后角斜角肌<span style="color:red;">紧张</span>，右侧胸锁乳突肌<span style="color:#5E92DD;">无力</span>。建议进行平衡训练。`,
                `右侧胸锁乳突肌<span style="color:red;">紧张</span>，左侧胸锁乳突肌和后角斜角肌<span style="color:#5E92DD;">无力</span>。建议进行平衡训练。`
                ],
                [
                    `左侧斜方肌上束<span style="color:red;">紧张</span>，中下束<span style="color:#5E92DD;">无力</span>。建议进行斜方肌中下束强化和上束放松训练。`,
                    `右侧斜方肌上束<span style="color:red;">紧张</span>，中下束<span style="color:#5E92DD;">无力</span>。建议进行斜方肌中下束强化和上束放松训练。`
                ],
                [
                    `髋内旋肌群和内收肌群<span style="color:red;">紧张</span>，臀中肌<span style="color:#5E92DD;">无力</span>。建议加强臀中肌，拉伸内收肌群。`,
                    `臀中肌和梨状肌<span style="color:red;">紧张</span>，髋内收肌群、内旋肌群和膝外侧副韧带<span style="color:#5E92DD;">无力</span>。建议加强内收肌群，拉伸臀中肌和梨状肌。`,
                    `臀中肌和梨状肌<span style="color:red;">紧张</span>，单侧髋内收肌群、内旋肌群和膝外侧副韧带<span style="color:#5E92DD;">无力</span>。建议保持均衡训练，避免单侧过度使用。`,
                    `建议保持均衡训练，避免单侧过度使用。`,
                    `左侧腘绳肌和膕肌<span style="color:red;">紧张</span>，股四头肌和比目鱼肌<span style="color:#5E92DD;">无力</span>。建议加强股四头肌，拉伸腘绳肌。`,
                    `左侧股四头肌<span style="color:red;">紧张</span>，臀大肌和胭绳肌<span style="color:#5E92DD;">无力</span>。建议加强臀大肌和胭绳肌，拉伸股四头肌。`,
                    `右侧腘绳肌和膕肌<span style="color:red;">紧张</span>，股四头肌和比目鱼肌<span style="color:#5E92DD;">无力</span>。建议加强股四头肌，拉伸腘绳肌。`,
                    `右侧股四头肌<span style="color:red;">紧张</span>，臀大肌和胭绳肌<span style="color:#5E92DD;">无力</span>。建议加强臀大肌和胭绳肌，拉伸股四头肌。`,
                ]
            ],
            errorArray: [],
            interval: [0, 6, 16, 31, 50],
            imgUrl: [
                require('../../assets/image/young/level1.png'),
                require('../../assets/image/young/level2.png'),
                require('../../assets/image/young/level3.png'),
                require('../../assets/image/young/level4.png')
            ],


        }
    },
    computed: {
        type1Color() {
            const data = {
                leftUp: dc,
                rightUp: dc,
                leftDown: dc,
                rightDown: dc
            }
            // 如果头前引，全部都是红色
            if ([1, 2].includes(this.spinalData.spineDetail.headForwardState)) {
                data.leftUp = red
                data.rightUp = red
                data.leftDown = red
                data.rightDown = red
            } else {
                // 判断头侧歪
                if ([2, 4].includes(this.spinalData.spineDetail.headSlantState)) {
                    // 右
                    data.leftUp = blue
                    data.rightUp = red
                } else if ([1, 3].includes(this.spinalData.spineDetail.headSlantState)) {
                     // 左
                    data.leftUp = red
                    data.rightUp = blue
                }
            }
            return data
        },
        type2Color() {
            const data = {
                leftUp: dc,
                rightUp: dc,
                leftDown: dc,
                rightDown: dc
            }
            // 判断高低肩
            if ([1, 3].includes(this.spinalData.spineDetail.highLowShoudlerState)) {
                // 右高左低
                data.rightUp = red
                data.rightDown = red
            } else if ([2, 4].includes(this.spinalData.spineDetail.highLowShoudlerState)) {
                // 左高右低
                data.leftUp = red
                data.leftDown = red
            }
            return data
        },
        type3Color() {
            const data = {
                leftUpIn: dc,
                leftUpOut: dc,
                rightUpIn: dc,
                rightUpOut: dc,
                leftMiddleIn: dc,
                leftMiddleOut: dc,
                rightMiddleIn: dc,
                rightMiddleOut: dc,
                leftDownIn: dc,
                leftDownOut: dc,
                rightDownIn: dc,
                rightDownOut: dc,
            }
            // 左膝
            if ([1, 3].includes(this.spinalData.spineDetail.leftKneeCheckState)) {
                // 左膝前屈
                data.leftUpIn = dc
                data.leftUpOut = dc
                data.leftMiddleIn = red
                data.leftMiddleOut = red
                data.leftDownIn = blue
                data.leftDownOut = blue
            } else if ([2, 4].includes(this.spinalData.spineDetail.leftKneeCheckState)) {
                // 左膝超伸
                data.leftUpIn = blue
                data.leftUpOut = blue
                data.leftMiddleIn = red
                data.leftMiddleOut = red
                data.leftDownIn = dc
                data.leftDownOut = dc
            }
            // 右膝
            if ([1, 3].includes(this.spinalData.spineDetail.rightKneeCheckState)) {
                // 右膝前屈
                data.rightUpIn = dc
                data.rightUpOut = dc
                data.rightMiddleIn = red
                data.rightMiddleOut = red
                data.rightDownIn = blue
                data.rightDownOut = blue
            } else if ([2, 4].includes(this.spinalData.spineDetail.rightKneeCheckState)) {
                // 右膝超伸
                data.rightUpIn = blue
                data.rightUpOut = blue
                data.rightMiddleIn = red
                data.rightMiddleOut = red
                data.rightDownIn = dc
                data.rightDownOut = dc
            }
            // 1. 无论左右，只要膝盖评估有膝超伸/膝前屈：按左右膝盖评估的肌肉效果显示，即序号33-36
            // 2.如果左右膝盖均无膝超伸/膝前屈：按腿型的肌肉效果图显示，即序号37-40
            if ([1, 3].includes(this.spinalData.spineDetail.leftKneeCheckState) || [2, 4].includes(this.spinalData.spineDetail.leftKneeCheckState) || [1, 3].includes(this.spinalData.spineDetail.rightKneeCheckState) || [2, 4].includes(this.spinalData.spineDetail.rightKneeCheckState)) {
                return data
            }
            // 腿型
            if ([4, 8].includes(this.spinalData.spineDetail.legType)) {
                // X
                data.leftUpIn = blue
                data.leftUpOut = blue
                data.leftMiddleIn = red
                data.leftMiddleOut = red
                data.rightUpIn = blue
                data.rightUpOut = blue
                data.rightMiddleIn = red
                data.rightMiddleOut = red
            } else if ([5, 9].includes(this.spinalData.spineDetail.legType)) {
                // O
                data.leftUpIn = red
                data.leftUpOut = red
                data.leftMiddleIn = blue
                data.leftMiddleOut = blue
                data.rightUpIn = red
                data.rightUpOut = red
                data.rightMiddleIn = blue
                data.rightMiddleOut = blue
            } else if (this.spinalData.spineDetail.legType === 2) {
                // K
            } else if ([3, 7].includes(this.spinalData.spineDetail.legType)) {
                // D
                data.leftUpIn = red
                data.leftUpOut = red
                data.rightUpIn = red
                data.rightUpOut = red
            }
            return data
        }
    },
    created() {
        this.init()
    },
    methods: {
        init() {
            this.tabinx = 0
            this.preScore = Math.round(this.spinalData.spineDetail.cervicalScore)
            this.preStatus = this.spinalData.spineDetail.cervicalStatus

            this.structuralDes = this.structuralArray[0][this.preStatus]
            this.interval = [0, 6, 16, 31, 50]
            this.handleTips()
            switch (this.spinalData.structureAssessment.spineStatus) {
                case 0:
                    this.structureAssessmentDes = "脊柱整体排列基本正常"
                    break
                case 1:
                    this.structureAssessmentDes = "脊柱结构轻度异常，建议加强姿势管理和核心肌群训练。"
                    break
                case 2:
                    this.structureAssessmentDes = "脊柱结构中度异常，建议专业矫正干预并定期复查评估。"
                    break
                case 3:
                    this.structureAssessmentDes = "脊柱结构重度异常，建议就医进行多学科会诊评估。"
                 break
            }

        },
        onChange(index) {
            this.tabinx = index
            switch (index) {
                case 0:
                    this.preScore = Math.round(this.spinalData.spineDetail.cervicalScore)
                    this.preStatus = this.spinalData.spineDetail.cervicalStatus
                    this.structuralDes = this.structuralArray[index][this.preStatus]
                    this.handleTips()
                    this.interval = [0, 6, 16, 31, 50]
                    break
                case 1:
                    this.preScore = Math.round(this.spinalData.spineDetail.thoracicScore)
                    this.preStatus = this.spinalData.spineDetail.thoracicStatus
                    this.structuralDes = this.structuralArray[index][this.preStatus]
                    this.handleTips()
                    this.interval = [0, 6, 16, 31, 50]
                    break
                case 2:
                    this.preScore = Math.round(this.spinalData.spineDetail.lumbarScore)
                    this.preStatus = this.spinalData.spineDetail.lumbarStatus
                    this.structuralDes = this.structuralArray[index][this.preStatus]
                    this.handleTips()
                    this.interval = [0, 6, 16, 31, 50]
                    break
            }
        },
        dealWith(key) {
            switch (key) {
                case 0:
                    return "正常"
                case 1:
                    return "轻度异常"
                case 2:
                    return "中度异常"
                case 3:
                    return "重度异常"
            }
        },
        handleTips() {
            this.errorArray = []
            if (this.tabinx === 0) {
                // 头前引
                if (this.spinalData.spineDetail.headForwardState) {
                    this.errorArray.push(this.errorTips[0][0])
                }
                if ([2, 4].includes(this.spinalData.spineDetail.headSlantState)) {
                    this.errorArray.push(this.errorTips[0][1])
                }
                if ([1, 3].includes(this.spinalData.spineDetail.headSlantState)) {
                    this.errorArray.push(this.errorTips[0][2])
                }
            }
            if (this.tabinx === 1) {
                if ([1, 3].includes(this.spinalData.spineDetail.highLowShoudlerState)) {
                    this.errorArray.push(this.errorTips[1][0])
                }
                if ([2, 4].includes(this.spinalData.spineDetail.highLowShoudlerState)) {
                    this.errorArray.push(this.errorTips[1][1])
                }
            }
            if (this.tabinx === 2) {
                // 腿型
                if ([4, 8].includes(this.spinalData.spineDetail.legType)) {
                    this.errorArray.push(this.errorTips[2][0])
                }
                if ([5, 9].includes(this.spinalData.spineDetail.legType)) {
                    this.errorArray.push(this.errorTips[2][1])
                }
                if ([3, 7].includes(this.spinalData.spineDetail.legType)) {
                    this.errorArray.push(this.errorTips[2][2])
                }
                if ([2, 6].includes(this.spinalData.spineDetail.legType)) {
                    this.errorArray.push(this.errorTips[2][3])
                }
                // 膝评估状态
                if ([1, 3].includes(this.spinalData.spineDetail.leftKneeCheckState)) {
                    this.errorArray.push(this.errorTips[2][4])
                }
                if ([2, 4].includes(this.spinalData.spineDetail.leftKneeCheckState)) {
                    this.errorArray.push(this.errorTips[2][5])
                }
                if ([1, 3].includes(this.spinalData.spineDetail.rightKneeCheckState)) {
                    this.errorArray.push(this.errorTips[2][6])
                }
                if ([2, 4].includes(this.spinalData.spineDetail.rightKneeCheckState)) {
                    this.errorArray.push(this.errorTips[2][7])
                }
            }
            if (this.errorArray.length === 0) {
                this.errorArray.push('肌肉评估正常，请继续保持良好的生活习惯')
            }
        }
    }
}
</script>

